// Integration framework views.
// Owner: Agent C (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { uuid } from './common';
import type { ConnectMethod, MarketplaceCategory, MarketplaceReason, MarketplaceStatus, PermissionGaps, ProviderReviewState, ReviewRequirement } from './marketplace';

export const integrationsContractsVersion = 1 as const;

export const integrationProviderId = z.string().regex(/^[a-z0-9_]{2,40}$/, 'provider id');
export const integrationEnvironment = z.enum(['sandbox', 'live']);
export type IntegrationEnvironment = z.infer<typeof integrationEnvironment>;

/**
 * Which system owns each resource while a connection is active:
 * - menu: 'resuto' (default) — Resuto is the menu of record; a provider pull never
 *   overwrites a product that already exists in Resuto with different data, it
 *   records an integration_conflicts row for a human to resolve.
 *   'provider' — the POS is the menu of record; differing rows are offered for
 *   import (B1's import endpoint applies them) and no conflict is recorded.
 * - orders: always 'resuto' — orders are created only through the Resuto kernel;
 *   no provider can create or modify Resuto orders (order push is not implemented).
 */
export const integrationSourceOfTruth = z.object({
  menu: z.enum(['resuto', 'provider']).optional(),
  orders: z.literal('resuto').optional(),
}).strict();
export type IntegrationSourceOfTruth = z.infer<typeof integrationSourceOfTruth>;
export const DEFAULT_INTEGRATION_SOURCE_OF_TRUTH: Required<IntegrationSourceOfTruth> = { menu: 'resuto', orders: 'resuto' };

const credentialMap = z.record(z.string().regex(/^[A-Za-z0-9_]{1,60}$/), z.string().min(1).max(4000));
const configMap = z.record(z.string().regex(/^[A-Za-z0-9_]{1,60}$/), z.union([z.string().max(500), z.number(), z.boolean(), z.null()]));

export const createIntegrationConnection = z.object({
  provider: integrationProviderId,
  branchId: uuid.nullable().optional(),
  environment: integrationEnvironment.default('sandbox'),
  credentials: credentialMap.default({}),
  config: configMap.default({}),
  sourceOfTruth: integrationSourceOfTruth.optional(),
}).strict();
export type CreateIntegrationConnection = z.infer<typeof createIntegrationConnection>;

export const updateIntegrationConnection = z.object({
  environment: integrationEnvironment.optional(),
  /** Replaces the stored credentials entirely when present. */
  credentials: credentialMap.optional(),
  config: configMap.optional(),
  sourceOfTruth: integrationSourceOfTruth.optional(),
}).strict();
export type UpdateIntegrationConnection = z.infer<typeof updateIntegrationConnection>;

export const integrationSyncRequest = z.object({
  resource: z.enum(['menu']),
  direction: z.literal('pull').default('pull'),
  /** Start from this provider cursor instead of the stored one (null = from the beginning). */
  cursor: z.string().max(200).nullable().optional(),
  maxPages: z.number().int().min(1).max(20).default(5),
}).strict();
export type IntegrationSyncRequest = z.infer<typeof integrationSyncRequest>;

export const resolveIntegrationConflict = z.object({ resolution: z.enum(['kept_local', 'kept_external', 'ignored']) }).strict();

/**
 * OAuth start (PS-11). `browserBinding` is the SHA-256 (hex) of a random nonce the browser keeps until the provider
 * sends it back; completing the flow needs that nonce and the same signed-in user.
 */
export const integrationOauthStart = z.object({
  redirectAfter: z.string().regex(/^\/(?!\/)[^\s]*$/).max(300).optional(),
  browserBinding: z.string().regex(/^[0-9a-f]{64}$/, 'SHA-256 hex of the browser nonce'),
}).strict();

/** OAuth completion, posted by the web app with the user's session after the provider redirected back. */
export const integrationOauthComplete = z.object({
  code: z.string().trim().min(1).max(2000),
  state: z.string().trim().min(16).max(200),
  browserNonce: z.string().regex(/^[A-Za-z0-9_-]{32,128}$/),
}).strict();
export type IntegrationOauthComplete = z.infer<typeof integrationOauthComplete>;

/** Picks the ad account / advertiser a connection uses, from the ones the provider granted. */
export const integrationAccountSelection = z.object({ accountId: z.string().trim().regex(/^[A-Za-z0-9_-]{1,64}$/) }).strict();

export type IntegrationReadiness = 'simulated' | 'implemented_unverified' | 'sandbox_verified' | 'live_verified';

export interface ProviderCatalogEntry {
  id: string;
  name: string;
  category: string;
  countries: string[];
  authType: string;
  readiness: IntegrationReadiness;
  activation: string[];
  docsUrl: string | null;
  capabilities: string[];
  /** True when the adapter only simulates (no provider involved). */
  sandboxOnly: boolean;
  /** 21-INT: how the restaurant connects it (descriptor `connectMethod`). */
  connectMethod?: ConnectMethod;
  /** 21-INT: marketplace filter. */
  marketplaceCategory?: MarketplaceCategory;
  /** 21-INT: provider scopes each capability needs (compared with the scopes the provider granted). */
  requiredScopes?: Record<string, string[]>;
  /** 21-INT: what the provider must grant before some capabilities work (App Review, business verification …). */
  reviewRequirements?: ReviewRequirement[];
}

/** 21-INT: the marketplace card state for one tenant (GET /o/:orgId/integrations/catalog, `marketplace`). */
export interface ProviderMarketplaceState {
  status: MarketplaceStatus;
  reasons: MarketplaceReason[];
  /** The tenant's connection the chip describes (org-level first), or null. */
  connectionId: string | null;
  /** The platform app's provider review as recorded by Resuto's operator ('unknown' = nothing recorded). */
  providerReview: ProviderReviewState | null;
}

/** 21-INT: granted scopes read back from the provider vs. the scopes each capability needs. */
export interface ConnectionPermissions extends PermissionGaps {
  /** Whether Resuto can read the granted scopes for this connection (and how). */
  source: 'token_response' | 'permissions_api' | null;
  checkable: boolean;
}

export interface IntegrationConnectionView {
  id: string;
  provider: string;
  category: string;
  branchId: string | null;
  authType: string;
  environment: IntegrationEnvironment;
  status: 'not_configured' | 'sandbox' | 'pending' | 'connected' | 'error' | 'revoked';
  enabled: boolean;
  credentialsHint: string | null;
  config: Record<string, unknown>;
  sourceOfTruth: Required<IntegrationSourceOfTruth>;
  health: Record<string, unknown>;
  lastHealthCheckAt: string | null;
  lastError: string | null;
  readiness: IntegrationReadiness | null;
  connectedAt: string | null;
  /** 21-INT: scopes the provider reported as granted (empty when it reports none or was not asked). */
  grantedScopes?: string[];
  createdAt: string;
  updatedAt: string;
}
